actions.script:
const L = (text) => ec.l10n.localize(text)
clusterList = []
clusterError = ''
noAddressText = ''
singleNoAddress = false
frontList = []
hasFront = false
front = {}
// a front node (the parent's frontNode) has the front set alone and dials no other node (plans/Edge-Node2.md §4.7)
frontRole = frontNode === true
pairsFront = false
if (!isEdge) return
let out = {}
// a probe (Practices-App-Dev §4): a failure is shown on the page rather than failing it
ec.message.pushErrors()
try {
    out = ec.service.sync().name('org.moqui.edge.EdgeServices.get#EdgeCluster').call() || {}
    if (ec.message.hasError()) clusterError = ec.message.getErrorsString()
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}
if (clusterError) return
const members = Array.from(out.memberList || [])
const age = (ms) => {
    if (ms == null) return L('None written')
    const seconds = Math.round(Number(ms) / 1000)
    return seconds < 120 ? seconds + ' s' : seconds < 7200 ? Math.round(seconds / 60) + ' min' : Math.round(seconds / 3600) + ' h'
}
clusterList = members.map((member) => {
    const url = String(member.linkUrl || '').trim()
    return {
        instanceId: member.instanceId + (member.thisMember ? ' (' + L('this node') + ')' : ''),
        liveLabel: member.live ? L('Live') : L('Stopped'), liveColor: member.live ? 'positive' : 'grey',
        // linkUrlUsable: what the Hello answer sends, an https URL with a host; any other address goes as none
        linkUrlText: !url ? L('None') : member.linkUrlUsable ? url : url + ' (' + L('not used: not an https address') + ')',
        heartbeatText: age(member.heartbeatAgeMs),
        // of the members' SIP engines only one registers the trunks, so a provider's calls go to one contact
        trunksText: member.registersTrunks ? L('Registers them') : '',
        version: member.version || ''}
})
const live = members.filter((member) => member.live)
const noAddress = live.filter((member) => !member.linkUrlUsable).map((member) => member.instanceId)
// a single edge node is dialed at the address its local nodes paired with: it needs no edge_link_url
if (live.length > 1) noAddressText = noAddress.join(', ')
else singleNoAddress = noAddress.length > 0
// the front node it is paired with: the link to each of the front's members, from the shared .env on every member
const states = {connecting: [L('Connecting'), 'info'], linked: [L('Linked'), 'positive'], retrying: [L('Retrying'), 'warning'],
    refused: [L('Refused'), 'negative'], unpaired: [L('Unpaired'), 'grey'], notStarted: [L('Not started here'), 'grey']}
const fronts = Array.from(out.frontList || [])
hasFront = fronts.length > 0
pairsFront = !hasFront && !frontRole
front = hasFront ? {name: fronts[0].frontName || fronts[0].url || L('Front node'),
    fingerprint: fronts[0].fingerprint || ''} : {}
frontList = fronts.map((link) => {
    const [stateLabel, stateColor] = states[link.state] || [link.state || '', 'grey']
    // front_node_id, where no front link runs, is the set of the front's member ids
    const ids = String(link.instanceId || '').split(',').map((id) => id.trim()).filter((id) => id).join(', ')
    return {instanceId: ids || L('Not known yet'), url: link.url || '', stateLabel, stateColor,
        rttText: link.rttMs != null ? ec.l10n.format(link.rttMs, '#,##0.0') + ' ms' : '',
        lastConnectText: link.lastConnectDate ? ec.l10n.format(link.lastConnectDate, '') : L('Not yet'),
        lastError: link.state !== 'linked' ? link.lastError || '' : ''}
})
